<?php require_once __DIR__.'/config.php';function mpesa_access_token(){if(!MPESA_CONSUMER_KEY||!MPESA_CONSUMER_SECRET)throw new RuntimeException('M-PESA Consumer Key/Secret not configured.');$ch=curl_init(MPESA_OAUTH_URL);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>1,CURLOPT_USERPWD=>MPESA_CONSUMER_KEY.':'.MPESA_CONSUMER_SECRET,CURLOPT_HTTPAUTH=>CURLAUTH_BASIC,CURLOPT_TIMEOUT=>30]);$b=curl_exec($ch);$c=curl_getinfo($ch,CURLINFO_HTTP_CODE);$e=curl_error($ch);curl_close($ch);if($b===false||$c<200||$c>=300)throw new RuntimeException('Daraja OAuth failed: HTTP '.$c.' '.$e.' '.$b);$d=json_decode($b,true);if(empty($d['access_token']))throw new RuntimeException('No access token returned.');return $d['access_token'];}function mpesa_stk_push($phone,$amount,$oid){if(!MPESA_SHORTCODE||!MPESA_PASSKEY)return ['success'=>false,'message'=>'M-PESA Shortcode and Passkey are not configured in config.php.'];$phone=preg_replace('/\D+/','',$phone);if(substr($phone,0,1)==='0')$phone='254'.substr($phone,1);$ts=date('YmdHis');$pwd=base64_encode(MPESA_SHORTCODE.MPESA_PASSKEY.$ts);$p=['BusinessShortCode'=>MPESA_SHORTCODE,'Password'=>$pwd,'Timestamp'=>$ts,'TransactionType'=>MPESA_STK_TYPE,'Amount'=>(int)round($amount),'PartyA'=>$phone,'PartyB'=>MPESA_SHORTCODE,'PhoneNumber'=>$phone,'CallBackURL'=>MPESA_CALLBACK_URL,'AccountReference'=>'SP-'.$oid,'TransactionDesc'=>MPESA_TRANSACTION_DESCRIPTION];$t=mpesa_access_token();$ch=curl_init(MPESA_STK_URL);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>1,CURLOPT_POST=>1,CURLOPT_POSTFIELDS=>json_encode($p),CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$t,'Content-Type: application/json'],CURLOPT_TIMEOUT=>30]);$b=curl_exec($ch);$c=curl_getinfo($ch,CURLINFO_HTTP_CODE);$e=curl_error($ch);curl_close($ch);if($b===false||$c<200||$c>=300)return ['success'=>false,'message'=>'STK request failed: HTTP '.$c.' '.$e.' '.$b];$d=json_decode($b,true);if((string)($d['ResponseCode']??'')==='0')return ['success'=>true]+$d;return ['success'=>false,'message'=>$d['errorMessage']??$d['ResponseDescription']??'Daraja rejected the request.'];}